create or replace function public.start_dungeon_run(target_character_id uuid,target_dungeon_location_id bigint)returns public.dungeon_runs language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;location public.world_locations%rowtype;position public.character_world_positions%rowtype;run public.dungeon_runs%rowtype;run_seed integer;room_count integer;room_type text;room_title text;rooms jsonb:='[]'::jsonb;begin select*into hero from public.characters where id=target_character_id and user_id=auth.uid();if hero.id is null then raise exception'character not found';end if;if exists(select 1 from public.character_life_profiles where character_id=hero.id and status<>'alive')then raise exception'character unavailable';end if;if exists(select 1 from public.dungeon_runs where character_id=hero.id and status='active')then raise exception'dungeon already active';end if;select*into location from public.world_locations where id=target_dungeon_location_id and location_type='dungeon'and active;if location.id is null then raise exception'dungeon not found';end if;select*into position from public.character_world_positions where character_id=hero.id;if position.location_id<>location.id then raise exception'dungeon location required';end if;run_seed:=abs(hashtext(gen_random_uuid()::text));room_count:=5+(run_seed%5);for room_index in 1..room_count loop if room_index=room_count then room_type:='boss';room_title:='บัลลังก์ผู้เฝ้าสุสาน';else room_type:=(array['combat','trap','treasure','rest'])[(run_seed+room_index*7)%4+1];room_title:=case room_type when'combat'then'โถงเสียงฝีเท้า'when'trap'then'ทางเดินอักษรรูน'when'treasure'then'ห้องเครื่องสักการะ'else'ศาลาพักวิญญาณ'end;end if;rooms:=rooms||jsonb_build_array(jsonb_build_object('index',room_index,'type',room_type,'title',room_title,'description',case room_type when'combat'then'เงาร่างเคลื่อนผ่านเสาหิน เตรียมรับการปะทะ'when'trap'then'กลไกโบราณซ่อนอยู่ใต้ลายสลัก'when'treasure'then'ประกายของสิ่งที่ถูกลืมรอผู้กล้า'when'rest'then'วงเวทสงบนิ่งพอให้หยุดพัก'else'ประตูสุดท้ายเปิดสู่ผู้ครองดันเจียน'end,'danger',least(10,location.danger_level+case when room_type='boss'then 2 else room_index/3 end),'cleared',false));end loop;insert into public.dungeon_runs(character_id,user_id,dungeon_location_id,seed,total_rooms,layout)values(hero.id,auth.uid(),location.id,run_seed,room_count,rooms)returning*into run;return run;end;$$;
